{
  "findings": [
    {
      "check_id": "CKV_AWS_261",
      "title": "Ensure that ALB target group is configured with HTTP health check",
      "resource": "aws_lb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "The target group is configured with TCP protocol but does not specify a health check protocol, which defaults to 'TCP'. It is recommended to use 'HTTP' for health checks to verify the health of the target instances."
    }
  ],
  "patched_code": "resource \"aws_lb_target_group\" \"pass\" {\n  name        = \"tf-example-lb-alb-tg\"\n  target_type = \"alb\"\n  port        = 80\n  protocol    = \"TCP\"\n  vpc_id      = aws_vpc.main.id\n  health_check {\n    protocol = \"HTTP\"\n    port     = \"traffic-port\"\n  }\n}",
  "fix_summary": "Added an HTTP health check configuration to the aws_lb_target_group resource."
}
